
/* ===== PARTE 8 — AK-47 REALISTA (modelo "Ak 47 Custom" de victor.alexandrems, CC BY) =====
   Troca so o visual do AK. Recuo, mira, mãos e recarga continuam os do jogo.
   Se der erro, se desliga e o AK antigo continua. */
(function(){
'use strict';
try{
if(typeof THREE==='undefined'||typeof WD==='undefined'||!WD[0]||!WD[0].rig||!WD[0].g||!WD[0].rig.mag)return;
const r=WD[0].rig,g=r.g,V3=THREE.Vector3;
const META=[["seletor", 0, 107, 94], ["ponta", 0, 519, 478], ["gatilho", 0, 236, 282], ["puxador", 0, 120, 97], ["guarda", 0, 1375, 2114], ["carregador", 0, 1461, 1310], ["coronha", 0, 4577, 4393], ["corpo", 1, 14511, 13365]];
const GEO='';
const IM={c0:'',o0:'',n0:'',c1:'',o1:'',n1:''};
const dec=s=>{const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u.buffer};
const load=src=>new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src='data:image/jpeg;base64,'+src});
const tx=im=>{const t=new THREE.Texture(im);t.flipY=false;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=4;t.needsUpdate=true;return t};
(async()=>{
 const ks=['c0','o0','n0','c1','o1','n1'],ims=await Promise.all(ks.map(k=>load(IM[k]))),T={};ks.forEach((k,i)=>T[k]=tx(ims[i]));
 const mk=i=>new THREE.MeshStandardMaterial({map:T['c'+i],metalnessMap:T['o'+i],roughnessMap:T['o'+i],normalMap:T['n'+i],metalness:1,roughness:1,envMapIntensity:1.1});
 const MT=[mk(0),mk(1)];
 /* le a geometria */
 const buf=dec(GEO);let nv=0,nt=0;META.forEach(m=>{nv+=m[2];nt+=m[3]});
 const oN=nv*12,oU=oN+nv*3,oI=oU+nv*8;
 const PS=new Float32Array(buf.slice(0,oN)),NS=new Int8Array(buf.slice(oN,oU)),US=new Float32Array(buf.slice(oU,oI)),IS=new Uint16Array(buf.slice(oI,oI+nt*6));
 const M={};let v0=0,t0=0;
 META.forEach(m=>{const n=m[2],t=m[3],ge=new THREE.BufferGeometry();
  const nn=new Float32Array(n*3);for(let i=0;i<n*3;i++)nn[i]=NS[v0*3+i]/127;
  ge.setAttribute('position',new THREE.BufferAttribute(PS.slice(v0*3,(v0+n)*3),3));
  ge.setAttribute('normal',new THREE.BufferAttribute(nn,3));
  ge.setAttribute('uv',new THREE.BufferAttribute(US.slice(v0*2,(v0+n)*2),2));
  ge.setIndex(new THREE.BufferAttribute(IS.slice(t0*3,(t0+t)*3),1));
  ge.computeBoundingSphere();
  M[m[0]]=new THREE.Mesh(ge,MT[m[1]]);v0+=n;t0+=t});
 /* acha o pivo do ferrolho (puxador) */
 const hd=g.children.find(o=>o.isGroup&&Math.abs(o.position.x-.075)<1e-4&&Math.abs(o.position.y-.04)<1e-4);
 const keep=new Set([r.mag,hd,g.userData.f,r.R.hand,r.R.fore,r.R.upper,r.L.hand,r.L.fore,r.L.upper]);
 g.children.forEach(o=>{if(!keep.has(o))o.visible=false});
 r.mag.children.forEach(o=>o.visible=false);if(hd)hd.children.forEach(o=>o.visible=false);
 if(r.ret&&r.ret.material)r.ret.material.visible=false;
 /* peças fixas */
 ['seletor','ponta','gatilho','guarda','coronha','corpo'].forEach(k=>{M[k].frustumCulled=false;g.add(M[k])});
 /* carregador acompanha o pivô */
 r.magHome.set(0,-.145,-.075);r.magOff.set(0,.07,.03);
 r.mag.position.copy(r.magHome);
 M.carregador.position.set(0,.145,.075);M.carregador.frustumCulled=false;r.mag.add(M.carregador);
 /* puxador acompanha o ferrolho */
 if(hd){M.puxador.position.set(-.075,-.04,.01);M.puxador.frustumCulled=false;hd.add(M.puxador)}else g.add(M.puxador);
 /* mãos: empunhadura e guarda-mão do modelo novo */
 r.restR.set(0,-.096,.12);r.restL.set(0,-.14,-.28);
 r.wpL=[[0,0,-.14,-.28],[.14,0,-.215,-.105],[.22,0,-.215,-.105],[.4,0,-.33,-.08],[.44,-.3,-.5,.1],[.5,-.3,-.5,.1],[.56,0,-.33,-.08],[.64,0,-.215,-.105],[.72,0,-.215,-.105],[.78,.05,.06,-.065],[.84,.05,.06,.005],[.9,.05,.06,.005],[.97,.05,.06,-.065],[1,0,-.14,-.28]];
 /* clarão do tiro na ponta do cano */
 const f=g.userData.f;if(f)f.position.set(0,.036,-.77);
 console.log('[ak-novo] ok');
})().catch(e=>{try{console.error('[ak-novo]',e)}catch(_){}});
}catch(e){try{console.error('[ak-novo]',e)}catch(_){}}
})();
